function sil = silence(nmat,nmatref,reson,thres);if isempty(nmat) sil=1; return; endsil = 0;o = onset(nmat,'sec');d = dur(nmat,'sec');or = onset(nmatref,'sec');dr = dur(nmatref,'sec');tmax = max(o(end)+d(end),or(end)+dr(end));t = tmax;i = size(o,1);while t>0    while t - o(i) - min(d(i),reson) < thres        t = o(i);        i = i-1;        if i == 0            sil = sil + o(1);            sil = sil/tmax;            return        end    end    sil = sil + (t - o(i) - min(d(i),reson) - thres);    t = o(i);    i = i-1;    if i == 0        sil = sil + o(1);        sil = sil/tmax;        return    endendsil = sil/tmax;